<?php
require_once __DIR__ . '/includes/auth.php';
require_staff();
$pdo=db();
$format=$_GET['format']??'csv';$q=trim((string)($_GET['q']??''));$from=trim((string)($_GET['from']??''));$to=trim((string)($_GET['to']??''));
$where=[];$params=[];
if($from!==''){$where[]='b.created_at >= ?';$params[]=$from.' 00:00:00';}
if($to!==''){$where[]='b.created_at < ?';$params[]=date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00';}
if($q!==''){$where[]='(b.case_no LIKE ? OR b.report_type LIKE ? OR b.incident_type LIKE ? OR b.complainant LIKE ? OR b.respondent LIKE ? OR b.location LIKE ?)';for($i=0;$i<6;$i++)$params[]='%'.$q.'%';}
$filter=$where?' WHERE '.implode(' AND ',$where):'';
$stmt=$pdo->prepare("SELECT b.case_no,b.report_type,b.incident_type,b.complainant,b.respondent,b.location,b.status,b.priority,b.incident_date,b.created_at FROM blotters b{$filter} ORDER BY b.created_at DESC");$stmt->execute($params);$rows=$stmt->fetchAll();
$statsStmt=$pdo->prepare("SELECT b.report_type,COUNT(*) total FROM blotters b{$filter} GROUP BY b.report_type ORDER BY total DESC");$statsStmt->execute($params);$stats=$statsStmt->fetchAll();
$docWhere=[];$docParams=[];if($from!==''){$docWhere[]='d.requested_at >= ?';$docParams[]=$from.' 00:00:00';}if($to!==''){$docWhere[]='d.requested_at < ?';$docParams[]=date('Y-m-d',strtotime($to.' +1 day')).' 00:00:00';}if($q!==''){$docWhere[]='(d.request_no LIKE ? OR d.document_type LIKE ? OR d.requester_name LIKE ? OR d.purpose LIKE ?)';for($i=0;$i<4;$i++)$docParams[]='%'.$q.'%';}$docFilter=$docWhere?' WHERE '.implode(' AND ',$docWhere):'';$docStatsStmt=$pdo->prepare("SELECT d.document_type,COUNT(*) total FROM document_requests d{$docFilter} GROUP BY d.document_type ORDER BY total DESC");$docStatsStmt->execute($docParams);$docStats=$docStatsStmt->fetchAll();$docRowsStmt=$pdo->prepare("SELECT d.request_no,d.document_type,d.requester_name,d.purpose,d.fee,d.status,d.requested_at FROM document_requests d{$docFilter} ORDER BY d.requested_at DESC");$docRowsStmt->execute($docParams);$docRows=$docRowsStmt->fetchAll();
$title='Barangay Report Register and Analytics';$generated=date('F d, Y h:i A');$signatory='Hon. Roberto Reyes, Punong Barangay';$period=($from?:'All time').($to?' to '.$to:'');
if($format==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="barangay-report-'.date('Y-m-d').'.csv"');$out=fopen('php://output','w');fputcsv($out,[$title]);fputcsv($out,['Generated',$generated]);fputcsv($out,['Report period',$period]);fputcsv($out,['Search',$q?:'None']);fputcsv($out,['Designated signatory',$signatory]);fputcsv($out,[]);fputcsv($out,['Case No.','Report Type','Incident','Complainant','Respondent','Location','Status','Priority','Incident Date','Created At']);foreach($rows as $row)fputcsv($out,$row);fputcsv($out,[]);fputcsv($out,['Analytics by incident report type']);fputcsv($out,['Report Type','Count']);foreach($stats as $stat)fputcsv($out,[$stat['report_type'],$stat['total']]);fputcsv($out,[]);fputcsv($out,['Document requests by type']);fputcsv($out,['Document Type','Count']);foreach($docStats as $stat)fputcsv($out,[$stat['document_type'],$stat['total']]);fputcsv($out,[]);fputcsv($out,['Document Request Register']);fputcsv($out,['Request No.','Document Type','Requester','Purpose','Fee','Status','Requested At']);foreach($docRows as $row)fputcsv($out,$row);fclose($out);exit;}
if($format==='word'){header('Content-Type: application/msword; charset=utf-8');header('Content-Disposition: attachment; filename="barangay-report-'.date('Y-m-d').'.doc"');echo '<html><meta charset="utf-8"><body><h1>'.h($title).'</h1><p>Generated: '.h($generated).'<br>Report period: '.h($period).'<br>Search: '.h($q?:'None').'<br>Designated signatory: '.h($signatory).'</p><h2>Analytics by report type</h2><table border="1" cellpadding="5"><tr><th>Report type</th><th>Count</th></tr>';foreach($stats as $stat)echo '<tr><td>'.h($stat['report_type']).'</td><td>'.h($stat['total']).'</td></tr>';echo '</table><h2>Document requests by type</h2><table border="1" cellpadding="5"><tr><th>Document type</th><th>Count</th></tr>';foreach($docStats as $stat)echo '<tr><td>'.h($stat['document_type']).'</td><td>'.h($stat['total']).'</td></tr>';echo '</table><h2>Itemized report register</h2><table border="1" cellpadding="5"><tr><th>Case</th><th>Type</th><th>Incident</th><th>Complainant</th><th>Respondent</th><th>Location</th><th>Status</th><th>Date</th></tr>';foreach($rows as $row)echo '<tr><td>'.h($row['case_no']).'</td><td>'.h($row['report_type']).'</td><td>'.h($row['incident_type']).'</td><td>'.h($row['complainant']).'</td><td>'.h($row['respondent']).'</td><td>'.h($row['location']).'</td><td>'.h($row['status']).'</td><td>'.h($row['incident_date']).'</td></tr>';echo '</table><br><br><p>Prepared by: '.h(current_user()['full_name']).'</p><p>_____________________________<br>'.h($signatory).'</p></body></html>';exit;}
function simple_pdf(array $lines): string {$objects=[];$objects[]='<< /Type /Catalog /Pages 2 0 R >>';$objects[]='<< /Type /Pages /Kids [3 0 R] /Count 1 >>';$objects[]='<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>';$stream="BT\n/F1 9 Tf\n50 750 Td\n";$lineCount=0;foreach($lines as $line){if($lineCount++>=46){$stream.="ET\nBT\n/F1 9 Tf\n50 750 Td\n";$lineCount=1;}$safe=str_replace(['\\','(',')'],['\\\\','\\(','\\)'],mb_substr((string)$line,0,110));$stream.='('.$safe.') Tj 0 -15 Td' . "\n";}$stream.="ET";$objects[]='<< /Length '.strlen($stream).' >>\nstream\n'.$stream.'\nendstream';$objects[]='<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>';$pdf="%PDF-1.4\n";$offsets=[0];foreach($objects as $i=>$object){$offsets[]=strlen($pdf);$pdf.=($i+1).' 0 obj\n'.$object.'\nendobj\n';}$xref=strlen($pdf);$pdf.='xref\n0 '.(count($objects)+1).'\n0000000000 65535 f \n';for($i=1;$i<=count($objects);$i++)$pdf.=str_pad((string)$offsets[$i],10,'0',STR_PAD_LEFT).' 00000 n \n';$pdf.='trailer\n<< /Size '.(count($objects)+1).' /Root 1 0 R >>\nstartxref\n'.$xref.'\n%%EOF';return $pdf;}
$lines=[$title,'Generated: '.$generated,'Report period: '.$period,'Search: '.($q?:'None'),'Designated signatory: '.$signatory,'','ANALYTICS BY REPORT TYPE'];foreach($stats as $stat)$lines[]=$stat['report_type'].': '.$stat['total'];$lines[]='';$lines[]='DOCUMENT REQUESTS BY TYPE';foreach($docStats as $stat)$lines[]=$stat['document_type'].': '.$stat['total'];$lines[]='';$lines[]='ITEMIZED REPORT REGISTER';foreach($rows as $row)$lines[]=$row['case_no'].' | '.$row['report_type'].' | '.$row['incident_type'].' | '.$row['complainant'].' | '.$row['status'].' | '.$row['created_at'];$lines[]='';$lines[]='Prepared by: '.current_user()['full_name'];$lines[]='Signature: __________________________';header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="barangay-report-'.date('Y-m-d').'.pdf"');echo simple_pdf($lines);exit;
